mapper.select:
SELECT
    COUNT(s.id)                 AS service_count,
    COUNT(DISTINCT s.elder_id)  AS elder_count,
    (
        SELECT COUNT(*)
        FROM follow_up_record f
        WHERE f.doctor_id = #{doctorId}
        AND f.is_deleted = 0
        AND f.follow_date >= #{startDate}
        AND f.follow_date <= #{endDate}
    )                           AS follow_up_count,
    AVG(s.rating)               AS avg_rating
FROM service_record s
WHERE s.doctor_id = #{doctorId}
AND s.is_deleted = 0
AND s.service_date >= #{startDate}
AND s.service_date <= #{endDate}
